/bin/bash -lc "python - <<'PY'
import json, urllib.request, urllib.parse
for page in range(1,8):
 url=f'https://quay.io/api/v1/repository/biocontainers/scanpy/tag/?limit=100&onlyActiveTags=true&page={page}'
 with urllib.request.urlopen(url) as x:d=json.load(x)
 for t in d.get('tags',[]):
  n=t.get('name','')
  if n.startswith(('1.10','1.11','1.9')): print(n,t.get('manifest_digest'))
 if not d.get('has_additional'): break
PY"

